/**
 * Write a checksum value into the checksum field
 * <code>buf[offset, offset + length)</code> of a header buffer.
 * The first <code>length - 2</code> bytes of the field receive the
 * octal digits of the value, written by
 * {@link IOUtils#putOctalDigits(long, byte[], int, int)}; the last
 * two bytes receive the checksum terminator, written by
 * {@link IOUtils#terminateChecksum(byte[], int, int)}. This method
 * writes no byte of the field itself.
 *
 * @param value The checksum value.
 * @param buf The header buffer to write into.
 * @param offset The offset of the checksum field in the buffer.
 * @param length The length of the checksum field.
 * @return The offset just past the field, <code>offset + length</code>.
 */
public static int putChecksumField(long value, byte[] buf, int offset, int length) {
    IOUtils.putOctalDigits(value, buf, offset, length - 2);
    IOUtils.terminateChecksum(buf, offset, length);
    return offset + length;
